/* Vision — the token sheet of the `web` template.
 *
 * A design system as DATA: no build step, no library, no import. Everything
 * below is a custom property or one rule that spends one, so a component
 * template only ever writes class names and a model defining a component at
 * runtime has a vocabulary it can reach without inventing colours.
 *
 * The four load-bearing behaviours, each named where it lives:
 *   1. the glass material (`backdrop-filter`)
 *   2. its fallback where there is no backdrop filter (`@supports`)
 *   3. the setting that switches the material off (`prefers-reduced-transparency`)
 *   4. the mode that hands every colour to the OS (`forced-colors`)
 *
 * Two adoption rules ride along, from the platform this borrows from: glass
 * lives on the NAVIGATION layer only and never on glass, and body text never
 * sits directly on it. Both are enforced by the cell at definition time; the
 * classes here are only what they are enforced ABOUT.
 */

:root {
  color-scheme: dark;

  /* ── The material ──────────────────────────────────────────────────────
   * Three tints, one blur. The brightness clamp is what keeps glass over a
   * dark backdrop from turning into a grey box and glass over a bright one
   * from washing out — the filter reads the backdrop, so the clamp is the
   * only part of the material that is not a colour. */
  --glass-tint: rgba(255, 255, 255, 0.10);
  --glass-tint-thin: rgba(255, 255, 255, 0.055);
  --glass-tint-thick: rgba(255, 255, 255, 0.17);
  --glass-blur: 32px;
  --glass-saturate: 180%;
  --glass-brightness: 1.08;
  --glass-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate))
    brightness(var(--glass-brightness));
  /* What the material becomes where it cannot exist. Opaque on purpose: a
   * translucent fill with no blur behind it is unreadable, not degraded. */
  --glass-opaque: #1c1c1f;

  /* What body content sits on inside a pane. The second adoption rule says
   * text never sits directly on the material; this is the fill it sits on
   * instead, dark enough to hold a foreground at every backdrop. */
  --inner-fill: rgba(0, 0, 0, 0.18);

  /* ── Vibrancy: three tiers of one foreground ───────────────────────────
   * White at three alphas rather than three greys, so the foreground picks up
   * whatever is behind it — which is the whole reason the material is
   * translucent in the first place. */
  --fg-primary: rgba(255, 255, 255, 0.94);
  --fg-secondary: rgba(255, 255, 255, 0.62);
  --fg-tertiary: rgba(255, 255, 255, 0.38);

  /* ── Concentric geometry ───────────────────────────────────────────────
   * The inner radius is DERIVED, never re-typed: a card inset by its own
   * padding inside a window has to curve tighter by exactly that padding, or
   * the two curves visibly disagree. */
  --r-window: 28px;
  --r-pad: 8px;
  --r-inner: calc(var(--r-window) - var(--r-pad));
  --r-control: 12px;
  --pad-window: 20px;
  --pad-inner: 14px;

  /* ── Rim light: asymmetric on purpose ──────────────────────────────────
   * The light is above, so the top edge catches it and the bottom edge only
   * separates the pane from what is under it. One symmetric border would read
   * as an outline; these two read as an edge. */
  --rim-top: inset 0 1px 0 rgba(255, 255, 255, 0.28);
  --rim-bottom: inset 0 -1px 0 rgba(0, 0, 0, 0.22);

  /* ── Spatial shadow: two parts ─────────────────────────────────────────
   * Contact and cast. One shadow can be either the small dark line that says
   * "this touches" or the wide soft one that says "this floats"; a floating
   * pane needs both or it looks pasted on. */
  --shadow-contact: 0 1px 2px rgba(0, 0, 0, 0.30);
  --shadow-cast: 0 24px 48px -12px rgba(0, 0, 0, 0.55);
  --shadow-spatial: var(--shadow-contact), var(--shadow-cast);

  /* ── Grain ─────────────────────────────────────────────────────────────
   * A very low-amplitude noise field over the material. It exists to break up
   * the banding a large blurred gradient produces on 8-bit displays; at this
   * opacity it is not a texture anybody should be able to name. */
  --grain-opacity: 0.035;
  --grain: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2'/></filter><rect width='120' height='120' filter='url(%23n)'/></svg>");

  /* ── Type: the visionOS weight bump ────────────────────────────────────
   * Body goes to medium and titles to bold, one step above the print-derived
   * defaults, because type over a translucent, moving backdrop needs the extra
   * stroke to hold its edge. */
  --font-ui: "SF Pro Text", "SF Pro", system-ui, -apple-system, "Segoe UI",
    Roboto, sans-serif;
  --w-body: 500;
  --w-title: 700;
  --t-caption: 0.75rem;
  --t-body: 0.9375rem;
  --t-title-3: 1.25rem;
  --t-title-2: 1.5rem;
  --t-title-1: 2rem;
  --leading-body: 1.5;
  --leading-title: 1.15;

  --bg-void: #0a0a0c;
  --gap: 12px;
}

html {
  background: var(--bg-void);
}

body {
  margin: 0;
  font-family: var(--font-ui);
  font-size: var(--t-body);
  font-weight: var(--w-body);
  line-height: var(--leading-body);
  color: var(--fg-primary);
  -webkit-font-smoothing: antialiased;
}

/* ── The glass classes ───────────────────────────────────────────────────
 * The closed set. A component template writes one of these three and nothing
 * else about the material; the cell refuses a `content`-layer component whose
 * class list contains any of them. */
.glass,
.glass--thin,
.glass--thick {
  position: relative;
  isolation: isolate;
  border-radius: var(--r-window);
  padding: var(--pad-window);
  background-color: var(--glass-tint);
  -webkit-backdrop-filter: var(--glass-filter);
  backdrop-filter: var(--glass-filter);
  box-shadow: var(--rim-top), var(--rim-bottom), var(--shadow-spatial);
}

.glass--thin {
  background-color: var(--glass-tint-thin);
  --glass-blur: 18px;
}

.glass--thick {
  background-color: var(--glass-tint-thick);
  --glass-blur: 48px;
}

.glass::after,
.glass--thin::after,
.glass--thick::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: var(--grain);
  opacity: var(--grain-opacity);
  pointer-events: none;
  z-index: -1;
}

/* Anything inset inside a pane curves by the derived radius. */
.glass > .inner,
.glass--thin > .inner,
.glass--thick > .inner {
  border-radius: var(--r-inner);
  padding: var(--pad-inner);
}

/* ── Scroll edge ─────────────────────────────────────────────────────────
 * Content does not stop at the pane's edge, it fades into it. The mask is on
 * the scroller so the fade follows the scroll instead of sitting over it. */
.scroll-edge {
  overflow-y: auto;
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0,
    #000 var(--pad-window),
    #000 calc(100% - var(--pad-window)),
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    transparent 0,
    #000 var(--pad-window),
    #000 calc(100% - var(--pad-window)),
    transparent 100%
  );
}

/* ── Type and layout helpers ─────────────────────────────────────────── */
.title-1,
.title-2,
.title-3 {
  font-weight: var(--w-title);
  line-height: var(--leading-title);
  margin: 0 0 var(--gap);
}

.title-1 { font-size: var(--t-title-1); }
.title-2 { font-size: var(--t-title-2); }
.title-3 { font-size: var(--t-title-3); }

.text { margin: 0 0 var(--gap); }
.text--secondary { color: var(--fg-secondary); }
.text--tertiary { color: var(--fg-tertiary); font-size: var(--t-caption); }

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  padding: var(--pad-window);
}

/* ── The nine components, as the classes they write ──────────────────
 * Everything below is what a shipped component template names. A component is
 * a row, not code, so its whole visual vocabulary has to exist here: a class a
 * template invents renders as nothing, and nothing is not a diagnosis.
 */

/* A stack in a row, for a toolbar or a badge line. It drops the window padding
 * because a row inside a pane is already inside that pane's padding. */
.stack--row {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  padding: 0;
}

/* A stack inside a stack is a group, not a window: it does not inset again,
 * or nesting one would cost the page another window's worth of padding. */
.stack .stack {
  padding: 0;
}

/* Card: a pane on the navigation layer. The card IS glass — that is why the
 * component declares `layer: "navigation"` and why the cell refuses to define
 * it as content. Its body goes in `.inner`, never straight onto the material. */
.card {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

.inner {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  background-color: var(--inner-fill);
}

/* Ornament: the floating dock. Fixed to the bottom edge, pill-shaped, and
 * glass — the other navigation-layer member of the set. It restates radius and
 * padding because it comes after the glass block and a dock is not a window. */
.ornament {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: var(--gap);
  padding: 10px 14px;
  border-radius: 999px;
  z-index: 10;
}

/* A heading one step up, for the one title a page leads with. A separate class
 * rather than `.title-1` in the same attribute: both would match, and the
 * later rule in this sheet would win regardless of the order they were written
 * in — which is not a thing a component author should have to know. */
.heading--lead {
  font-size: var(--t-title-1);
}

/* Table: tabular figures, a rule between rows, and a header row that reads as
 * a label rather than as content. */
.table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.table caption {
  caption-side: top;
  text-align: left;
  margin-bottom: var(--gap);
}

.table th,
.table td {
  text-align: left;
  padding: 6px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.table th {
  font-size: var(--t-caption);
  font-weight: var(--w-title);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fg-secondary);
}

.table tr:last-child td {
  border-bottom: 0;
}

/* Button: a control, so it takes the control radius rather than the window
 * one, and the rim light without the cast shadow — it sits on a pane, it does
 * not float above one. */
.button {
  font: inherit;
  font-weight: var(--w-title);
  color: var(--fg-primary);
  background-color: rgba(255, 255, 255, 0.14);
  border: 0;
  border-radius: var(--r-control);
  padding: 8px 16px;
  cursor: pointer;
  box-shadow: var(--rim-top), var(--shadow-contact);
  transition: background-color 120ms ease, transform 120ms ease;
}

.button:hover {
  background-color: rgba(255, 255, 255, 0.22);
}

.button:active {
  transform: scale(0.97);
}

.button:focus-visible,
.input:focus-visible {
  outline: 2px solid var(--fg-primary);
  outline-offset: 2px;
}

/* Input: a well rather than a raised control — darker than what is around it,
 * so it reads as somewhere to put something. */
.input {
  font: inherit;
  color: var(--fg-primary);
  background-color: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: var(--r-control);
  padding: 8px 12px;
  width: 100%;
  box-sizing: border-box;
}

.input::placeholder {
  color: var(--fg-tertiary);
}

/* Badge: a caption in a pill. Secondary by default, because a badge that
 * shouted would compete with the thing it labels. */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--t-caption);
  font-weight: var(--w-title);
  color: var(--fg-secondary);
  background-color: rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  padding: 2px 10px;
}

/* ── No backdrop filter: the material becomes an opaque pane ─────────────
 * Not a degraded glass — a different, honest surface. Translucency without a
 * blur behind it is text over noise. */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .glass,
  .glass--thin,
  .glass--thick {
    background-color: var(--glass-opaque);
  }
}

/* ── The viewer asked for less transparency ────────────────────────────── */
@media (prefers-reduced-transparency: reduce) {
  .glass,
  .glass--thin,
  .glass--thick {
    background-color: var(--glass-opaque);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .glass::after,
  .glass--thin::after,
  .glass--thick::after {
    display: none;
  }
}

/* ── The viewer asked for more contrast ────────────────────────────────── */
@media (prefers-contrast: more) {
  :root {
    --fg-secondary: rgba(255, 255, 255, 0.82);
    --fg-tertiary: rgba(255, 255, 255, 0.66);
    --rim-top: inset 0 0 0 1px rgba(255, 255, 255, 0.55);
  }

  .glass,
  .glass--thin,
  .glass--thick {
    background-color: var(--glass-opaque);
  }
}

/* ── Forced colours: the OS owns every colour, and we get out of the way ── */
@media (forced-colors: active) {
  .glass,
  .glass--thin,
  .glass--thick {
    background-color: Canvas;
    color: CanvasText;
    border: 1px solid CanvasText;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    box-shadow: none;
    forced-color-adjust: none;
  }

  .glass::after,
  .glass--thin::after,
  .glass--thick::after {
    display: none;
  }

  .button,
  .input,
  .badge,
  .inner {
    background-color: Canvas;
    color: CanvasText;
    border: 1px solid CanvasText;
    box-shadow: none;
    forced-color-adjust: none;
  }

  .scroll-edge {
    -webkit-mask-image: none;
    mask-image: none;
  }
}

/* ── Motion ──────────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
